+function parcelas(totalCentavos, n) {
+  if (!Number.isInteger(n) || n < 1) {
+    throw new RangeError('n deve ser um inteiro >= 1');
+  }
+
+  const base = Math.floor(totalCentavos / n);
+  const sobra = totalCentavos % n;
+
+  const result = [];
+  for (let i = 0; i < n; i++) {
+    result.push(base + (i < sobra ? 1 : 0));
+  }
+
+  return result;
+}
+
+module.exports = { brl, centavos, parcelas };
